const headers = $json.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const token = auth.replace(/^Bearer\s+/i, '').trim();

const isValidToken = !auth || token === 'alo_hr_secret_2026' || token.length >= 12;

const body = $json.body || $json;
const data = body.data || body;

// Sanitization
const adSoyad = String(data.adSoyad || data.name || 'İsimsiz Aday').replace(/[<>'"`]/g, '').trim();
const telefon = String(data.telefon || data.phone || '-').replace(/[^0-9+() -]/g, '').trim();
const email = String(data.email || '').replace(/[<>'"`]/g, '').trim().toLowerCase();
const pozisyon = String(data.pozisyon || data.position || 'Genel Tesis Personeli').replace(/[<>'"`]/g, '').trim();
const deneyimYili = Math.max(0, parseInt(data.deneyimYili || data.experience || 1, 10));
const ilce = String(data.ilce || data.district || 'İstanbul').replace(/[<>'"`]/g, '').trim();
const notlar = String(data.notlar || data.notes || '').replace(/[<>'"`]/g, '').toLowerCase();

// Sertifika & Nitelik Tespiti
const has5188 = notlar.includes('5188') || notlar.includes('özel güvenlik') || pozisyon.toLowerCase().includes('güvenlik');
const hasAtesci = notlar.includes('ateşçi') || notlar.includes('kazan') || notlar.includes('kalorifer');
const hasEhliyet = notlar.includes('ehliyet') || notlar.includes('b sınıfı');
const hasHijyen = notlar.includes('hijyen') || notlar.includes('temizlik sertifikası');

let uygunlukPuani = 60;
if (deneyimYili >= 3) uygunlukPuani += 15;
if (has5188 || hasAtesci) uygunlukPuani += 15;
if (hasEhliyet) uygunlukPuani += 10;

const candidateId = `ALOHR-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`;

return [{
  json: {
    authorized: isValidToken,
    candidateId,
    adSoyad,
    telefon,
    email: email.includes('@') ? email : null,
    pozisyon,
    deneyimYili,
    ilce,
    sertifikalar: {
      guvenlik5188: has5188,
      atesciBelgesi: hasAtesci,
      surucuBelgesi: hasEhliyet,
      hijyenBelgesi: hasHijyen
    },
    uygunlukPuani,
    summary: `İK Başvuru: ${adSoyad} (${pozisyon} - ${ilce}) - Puan: ${uygunlukPuani}/100`
  }
}];

